package com.ecole.gestion_scolaire.attendance.controller; import com.ecole.gestion_scolaire.attendance.dto.*; import com.ecole.gestion_scolaire.attendance.enums.StudentAttendanceStatus; import com.ecole.gestion_scolaire.attendance.service.StudentAttendanceService; import com.ecole.gestion_scolaire.common.dto.PageResponse; import jakarta.validation.Valid; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.time.LocalDate; import java.util.List;
@RestController @RequestMapping("/api/student-attendance") public class StudentAttendanceController { private final StudentAttendanceService service; public StudentAttendanceController(StudentAttendanceService s){service=s;}
 @GetMapping("/expected") @PreAuthorize("hasAuthority('ASSIDUITE_ELEVE_CONSULTER')") public List<ExpectedStudentAttendanceResponse> expected(@RequestParam LocalDate date,@RequestParam Long classGroupId,@RequestParam Long timeSlotId){return service.expected(date,classGroupId,timeSlotId);}
 @PutMapping("/batch") @PreAuthorize("hasAuthority('ASSIDUITE_ELEVE_SAISIR')") public List<StudentAttendanceResponse> save(@Valid @RequestBody StudentAttendanceBatchRequest r){return service.saveBatch(r);}
 @GetMapping @PreAuthorize("hasAuthority('ASSIDUITE_ELEVE_CONSULTER')") public PageResponse<StudentAttendanceResponse> history(@RequestParam(required=false) LocalDate from,@RequestParam(required=false) LocalDate to,@RequestParam(required=false) Long studentId,@RequestParam(required=false) Long classGroupId,@RequestParam(required=false) StudentAttendanceStatus status,@RequestParam(required=false) Boolean justified,@RequestParam(defaultValue="0") int page,@RequestParam(defaultValue="20") int size){return service.history(from,to,studentId,classGroupId,status,justified,page,size);}
 @GetMapping("/summary") @PreAuthorize("hasAuthority('ASSIDUITE_ELEVE_CONSULTER')") public StudentAttendanceSummaryResponse summary(@RequestParam(required=false) LocalDate from,@RequestParam(required=false) LocalDate to,@RequestParam(required=false) Long studentId,@RequestParam(required=false) Long classGroupId){return service.summary(from,to,studentId,classGroupId);}
}
